import boto3
from typing import Dict, Any


def get_secrets_manager_client(config: Dict[str, Any]) -> Any:
    region_name = config.get("region")
    if not region_name:
        raise ValueError("AWS region must be provided in config.")
    return boto3.client("secretsmanager", region_name=region_name)

import json

from security_client import get_secrets_manager_client
from security_models import SecretPayload, SecretResponse


def fetch_db_secret(payload: SecretPayload, config: dict) -> SecretResponse:
    client = get_secrets_manager_client(config)
    response = client.get_secret_value(SecretId=payload.secret_id)
    secret_string = response.get("SecretString")
    secret_binary = response.get("SecretBinary")

    if secret_string:
        db_secret = json.loads(secret_string)
    elif secret_binary:
        db_secret = json.loads(secret_binary.decode("utf-8"))
    else:
        raise ValueError("Secret does not contain SecretString or SecretBinary.")

    return SecretResponse(secret_value=db_secret, metadata=response)

import json

from security_client import get_secrets_manager_client
from security_models import SecretPayload, SecretResponse


def parse_json_secret(payload: SecretPayload, config: dict) -> SecretResponse:
    client = get_secrets_manager_client(config)

    # Construct the arguments for get_secret_value
    kwargs = {
        "SecretId": payload.secret_id
    }
    if payload.version_id:
        kwargs["VersionId"] = payload.version_id
    if payload.version_stage:
        kwargs["VersionStage"] = payload.version_stage

    response = client.get_secret_value(**kwargs)
    secret_value = response.get("SecretString") or response.get("SecretBinary").decode("utf-8")

    if secret_value:
        parsed_secret = json.loads(secret_value)
        if payload.key_field:
            parsed_secret = parsed_secret[payload.key_field]
        return SecretResponse(secret_value=parsed_secret, metadata=response)
    else:
        raise ValueError("Secret does not contain SecretString or SecretBinary.")

from security_client import get_secrets_manager_client
from security_models import SecretPayload, SecretResponse


def rotate_secret_version(payload: SecretPayload, config: dict) -> SecretResponse:
    if not payload.version_id and not payload.version_stage:
        raise ValueError("Either version_id or version_stage must be provided to read a specific secret version.")

    client = get_secrets_manager_client(config)

    kwargs = {
        "SecretId": payload.secret_id
    }
    if payload.version_id:
        kwargs["VersionId"] = payload.version_id
    if payload.version_stage:
        kwargs["VersionStage"] = payload.version_stage

    response = client.get_secret_value(**kwargs)
    secret_value = response.get("SecretString") or response.get("SecretBinary").decode("utf-8")

    return SecretResponse(secret_value=secret_value, metadata=response)
